INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('subarray-sum-k', 8, NULL, 'def gen():
    _s = [117757025]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    V = 3
    K = 0
    N = 200000
    a = [r(-V, V) for _ in range(N)]
    return f"{N} {K}\n{'' ''.join(map(str, a))}\n"
', '14791249', 0);
