INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('longest-unique', 9, NULL, 'def gen():
    _s = [1408149999]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    A = 94
    N = 200000
    return "".join(chr(33 + r(0, A - 1)) for _ in range(N)) + "\n"
', '43', 0);
INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('longest-unique', 10, NULL, 'def gen():
    _s = [1156413817]
